<!--
  试听按钮 (全局互斥播放), 配音记录列表与参考音频列表共用。

  播放本身交给 `lib/audio.ts` 的**全局单例** —— 这是「任意时刻只有一个在响」的落点。
  组件只负责: 把音频文件读成可播放的 blob URL (用完撤销)、订阅单例知道"现在响的是不是我",
  以及显示播放/停止两种状态 —— 播放中按钮进入 `playing` 态, 于是列表里几十条音频中
  "现在响的是哪一条"一目了然。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import { onDestroy } from 'svelte';

  import { subscribeAudio, toggleAudio } from '../lib/audio';
  import { readImageUrl } from '../lib/localImage.svelte';
  import Icon from './Icon.svelte';

  let {
    /** 音频文件的绝对路径; null 表示这条记录还没有音频 */
    path,
    /** 全局唯一标识 (用记录 id 即可) */
    key,
    /** 悬浮提示里的补充说明 (通常是参考文本) */
    label,
  }: {
    path: string | null;
    key: string;
    label?: string;
  } = $props();

  /** 当前正在响的记录的 key (单例广播) */
  let playing = $state<string | null>(null);
  let loading = $state(false);
  let error = $state<string | null>(null);
  /** 已经造出来的 blob URL, 卸载或换文件时撤销 */
  let blobUrl: string | null = null;
  let blobPath: string | null = null;

  const unsubscribe = subscribeAudio((next) => (playing = next));

  onDestroy(() => {
    unsubscribe();
    if (blobUrl) URL.revokeObjectURL(blobUrl);
  });

  const isPlaying = $derived(playing === key);
  const disabled = $derived(!path || loading);
  /** 悬浮提示 (同时用作 `title` 与 `aria-label`) */
  const hint = $derived(isPlaying ? '停止试听' : `试听${label ? `：${label}` : ''}`);

  async function ensureUrl(target: string): Promise<string | null> {
    // 同一个文件复用已造的 URL: 反复点同一个按钮不该反复读盘
    if (blobUrl && blobPath === target) return blobUrl;
    if (blobUrl) URL.revokeObjectURL(blobUrl);
    blobUrl = null;
    blobPath = null;

    const url = await readImageUrl(target);
    // 读盘期间可能又点了别的, 或者组件已经走了
    if (!url) return null;
    blobUrl = url;
    blobPath = target;
    return url;
  }

  async function toggle(): Promise<void> {
    const target = path;
    if (!target) return;

    // 正在响的这一条: 直接停, 不用再读盘
    if (isPlaying) {
      toggleAudio('', key);
      return;
    }

    loading = true;
    error = null;
    try {
      const url = await ensureUrl(target);
      if (!url) {
        error = '读不到音频文件';
        return;
      }
      toggleAudio(url, key);
    } catch (e) {
      error = String(e);
    } finally {
      loading = false;
    }
  }
</script>

<button
  type="button"
  class="git-file-action"
  class:playing={isPlaying}
  {disabled}
  title={error ?? hint}
  aria-label={hint}
  onclick={(event) => {
    // 卡片/记录行本身有"选中"语义, 点试听不该顺带把它选中
    event.stopPropagation();
    void toggle();
  }}
>
  <Icon name={isPlaying ? 'Stop' : 'Play'} size={14} />
</button>
